# -*- coding: utf-8; mode: shell-script; tab-width: 4 -*-
#-- get/create orig --------------------------------------------------------

# build the upstream orig file from:
# - from-rule: regenerated by "debian/rules get-orig-source"
# - uscan
# - from "local" files
function cmd:orig {
##:orig:cmd:generate or download the .orig. file. See 'ian help orig'.
##:orig:usage:ian orig [mode]
##:orig:usage:  mode;    the way to create orig [rule|uscan|local]
##:orig:usage:
##:orig:usage:  - rule;  run debian/rules "get-orig-source" rule to get/build .orig.
##:orig:usage:  - uscan; run uscan to download the .orig.
##:orig:usage:  - local; create an .orig. from current directory contents.

    local mode="${__args__[@]}"
    assert-no-more-args

    sc-assert-file-absent "$(find-orig-path)"

    if [ -z "$mode" ]; then
        local mode=$(_detect-orig-mode)
        log-ok "aplying detected orig mode: $mode"
    else
        log-info "orig mode: $mode"
    fi

    case $mode in
    rule)
    local orig_func="orig-from-rule"
    ;;

    uscan)
    local orig_func="orig-uscan"
    ;;

    local)
    local orig_func="orig-from-local"
    ;;

    *)
    log-error "wrong orig mode: $mode. See 'ian help orig'"
    exit 1
    ;;
    esac

    (
    assert-preconditions
	if [ ! -z $(find-orig-path) ]; then
        log-warning "missing orig '$(_orig-pattern)', getting/creating it"
	fi
    if _orig-needs-clean $mode; then
        ian-run clean
    fi
    sc-assure-dir $(orig-dir)

    $orig_func

    sc-assert-any-file-exists "$(orig-dir)" "$(_orig-pattern)"
    log-ok "orig"
    )
}

# uscan downloads the orig. "local" packs the working directory: build products must not get into the orig, but on a clean tree, as in "ian clean" + "ian build", cleaning again is useless. "rule" is up to the package, so it always cleans, just in case
function _orig-needs-clean {
    local mode="$1"

    case $mode in
    uscan) return 1 ;;
    rule)  return 0 ;;
    *)     _tree-seems-built ;;
    esac
}

# true if a build left its products in the working directory and no "clean" removed them since
function _tree-seems-built {
    local path=

    for path in debian/files debian/debhelper-build-stamp debian/.debhelper debian/tmp \
                debian/*.debhelper.log debian/*.substvars; do
        if [ -e "$path" ]; then
            return 0
        fi
    done

    for path in $(binary-names); do
        if [ -d "debian/$path" ]; then
            return 0
        fi
    done

    return 1
}

function cmd:orig-from-rule {
    (>&2 deprecation "command orig-from-rule is DEPRECATED. Use 'ian orig rule'")
    ian-run orig rule
}

function cmd:orig-uscan {
    (>&2 deprecation "command orig-uscan is DEPRECATED. Use 'ian orig uscan'")
    ian-run orig uscan
}

function cmd:orig-from-local {
    (>&2 deprecation "command orig-from-local is DEPRECATED. Use 'ian orig local'")
    ian-run orig local
}


function orig-from-rule {
    sc-assert _has-rule get-orig-source "missing 'get-orig-source' in 'debian/rules'"

    sh-check "make -f ./debian/rules get-orig-source"

    # the rule may leave the orig here or directly in the orig dir
    local fname
    for fname in $(eval echo $(_orig-pattern)); do
        if [ -f "$fname" ]; then
            mv -v "$fname" $(orig-dir)/
        fi
    done
}

# http://people.debian.org/~piotr/uscan-dl
function orig-uscan {
    _assert-valid-watch

    sh-check "uscan --verbose --download-current-version --force-download --repack --rename --destdir $(orig-dir)"
}

function orig-from-local {
    local orig_tmp=$(upstream-fullname)
    mkdir -p $orig_tmp

    local EXCLUDE="--exclude=$orig_tmp --exclude=./debian --exclude=\*~ --exclude-vcs --exclude=\*.pyc --exclude .pc"

    tar $EXCLUDE -cf - . | ( cd $orig_tmp && tar xf - )
    tar czf $(_orig-default) $orig_tmp
    \rm -rf $orig_tmp

	log-ok "orig file created: $(find-orig-path)"
}

# clean, orig
function orig-dir {
    echo ..
}

function _orig-pattern {
    # find . -type f \( -name "$(package)_$(upstream-version).orig.tar.xz" -o -name "$(package)_$(upstream-version).orig.tar.gz" \)
    echo $(package)_$(upstream-version).orig.tar.'{g,x}'z
}

function _orig-default {
    echo $(orig-dir)/$(package)_$(upstream-version).orig.tar.gz
}

# repo, orig, path
function find-orig-filename {
    if [ -z "$1" ]; then
        basename "$1"
    fi
}

# orig, build, summary
function find-orig-path {
    for fname in $(eval echo $(_orig-pattern)); do
        if sc-file-exists "$(orig-dir)/$fname"; then
            echo "$(orig-dir)/$fname"
            return
        fi
    done
}

function _detect-orig-mode {
    echo $(orig-modes) | awk '{print $1;}'
}

# summary
function orig-modes {
    if _has-rule get-orig-source; then
        methods[0]='rule'
    fi
    if valid-watch-present; then
        methods[1]='uscan'
    fi
    # if [ $(ls | wc -l) -gt 1 ]; then
		methods[2]='local'
    # fi

    # if [ ${#methods[@]} -eq 0 ]; then
		# echo "none!"
		# return
    # fi

    echo "${methods[@]}"
}

function _has-rule {
    grep -qs "^$1:" debian/rules
}

function _assert-valid-watch {
    sc-assert valid-watch-present
}
